import re

content = open('compose/sketchpad/sketchpad/Sketchpad.tsx').read()

# Find all duplicate declarations and their sections
# Strategy: Search for each known duplicate and rename based on containing region

# First, let's collect regions to understand context
region_stack = []
line_region_map = {}  # line_num -> current region name
lines = content.split('\n')

for i, line in enumerate(lines):
    stripped = line.strip()
    m = re.match(r'// #region 🔖(\w+)', stripped)
    if m:
        region_stack.append(m.group(1))
    elif stripped.startswith('// #endregion'):
        if region_stack:
            region_stack.pop()
    line_region_map[i] = region_stack[-1] if region_stack else ''

# Now find duplicates to fix
# Pattern: find all `const XYZ =` or `export const XYZ` declarations
# and track which region they're in

declarations = {}
for i, line in enumerate(lines):
    stripped = line.strip()

    # Check for const declarations of known problematic names
    for name in ['DiagramWindow', 'App', 'KitSection', 'TableWindow']:
        pat = f'const {name}'
        if pat in stripped and ('export ' in stripped or stripped.startswith('const ')):
            region = line_region_map.get(i, 'unknown')
            if name not in declarations:
                declarations[name] = []
            declarations[name].append((i, region))

print("Duplicate declarations found:")
for name, locs in declarations.items():
    if len(locs) > 1:
        print(f"  {name}:")
        for line_num, region in locs:
            print(f"    Line {line_num+1}: in region {region}")

# Also find export default statements
defaults = []
for i, line in enumerate(lines):
    if line.strip().startswith('export default'):
        region = line_region_map.get(i, 'unknown')
        defaults.append((i, region, line.strip()))

print(f"\nDefault exports ({len(defaults)}):")
for line_num, region, text in defaults:
    print(f"  Line {line_num+1}: {text} (region: {region})")
PYEOF

