content = open('compose/sketchpad/sketchpad/Sketchpad.tsx').read()
lines = content.split('\n')

# Strategy: We need to rename within each app section.
# We know the section boundaries from the region markers #region 🔖Design, #region 🔖Type, etc.
# 
# Approach: Identify ranges for each app section and rename within those ranges.

# Find section boundaries using the text "#region 🔖" markers
sections = []
for i, line in enumerate(lines):
    stripped = line.strip()
    if '// #region 🔖Design' == stripped:
        sections.append(('Design', i))
    elif '// #region 🔖Type' == stripped:
        sections.append(('Type', i))
    elif '// #region 🔖Kit' == stripped:
        sections.append(('Kit', i))
    elif '// #region 🔖Quality' == stripped:
        sections.append(('Quality', i))
    elif '// #region 🔖Home' == stripped:
        sections.append(('Home', i))
    elif '// #region 🔖Docs' == stripped:
        sections.append(('Docs', i))
    elif '// #region 🔖Feedback' == stripped:
        sections.append(('Feedback', i))

# Add endregion markers
for i in range(len(sections)):
    region_name = sections[i][0]
    start = sections[i][1]
    # Find matching endregion
    depth = 0
    end = len(lines) - 1
    for j in range(start, len(lines)):
        if '// #region' in lines[j].strip():
            depth += 1
        if '// #endregion' in lines[j].strip():
            depth -= 1
            if depth == 0:
                end = j
                break
    sections[i] = (region_name, start, end)

print("Found app sections:")
for name, start, end in sections:
    print(f"  {name}: lines {start+1}-{end+1}")

# Now we need the LAST occurrence of each section (the one in the Apps region)
# The earlier sections are in SketchpadCore
app_sections = {}
for name, start, end in sections:
    app_sections[name] = (start, end)

print("\nApp sections (last occurrence):")
for name, (start, end) in app_sections.items():
    print(f"  {name}: lines {start+1}-{end+1}")
