 * [👤compose📚js🗃️sketchpad💻tutorials🔖components🔖commandinterceptor🪨usetutorial
commandinterceptor](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Tutorials.tsx/s/Components/s/Command%20Interceptor/d/i/useTutorialCommandInterceptor)        **/
export const useTutorialCommandInterceptor = (onCommandExecute: (command: string
, origin?: string, args?: any) => void) => {                                      const store = useTutorialStore();
  const isRecording = useIsRecording();
  return useCallback(
    (command: string, origin?: string, args?: any) => {
      if (isRecording) {
        store.recordEvent({
          type: "command",
          data: { command, origin, args },
        });
      }
      store.checkCommandCompletion(command, origin, args);
      onCommandExecute(command, origin, args);
    },
    [store, isRecording, onCommandExecute],
  );
};

